-- =============================================================================
-- shoppingwebsite — DDL for the PostgreSQL tables
-- Loaded by the "seed" service: docker compose --profile seed up -d
-- Replaces the old DynamoDB table definitions (usertable.json, products.json,
-- productcategorytable.json, shoppingcart.json, Orders.json).
--
-- Columns mirror the JPA entities in src/main/java/.../dao so Hibernate's
-- ddl-auto: update finds nothing to change.
-- Seed rows follow the table definitions below.
-- =============================================================================

-- ---------------------------------------------------------------------------
-- users            (DynamoDB: users, HASH email, GSI useridx_id on userid)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS users (
    userid        VARCHAR(255) PRIMARY KEY,
    email         VARCHAR(255) NOT NULL UNIQUE,
    name          VARCHAR(255),
    imageurl      VARCHAR(255),
    enabled       BOOLEAN,
    password      VARCHAR(255),
    provider      VARCHAR(255)
                      CHECK (provider IN ('local', 'facebook', 'google')),
    providerid    VARCHAR(255),
    createddate   TIMESTAMP,
    modifieddate  TIMESTAMP
);

-- User.role (Set<String>) -> element collection
CREATE TABLE IF NOT EXISTS user_roles (
    userid  VARCHAR(255) NOT NULL REFERENCES users(userid),
    role    VARCHAR(255) NOT NULL,
    PRIMARY KEY (userid, role)
);

-- ---------------------------------------------------------------------------
-- productcategory  (DynamoDB: productcategory, HASH type)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS productcategory (
    type  VARCHAR(255) PRIMARY KEY,
    name  VARCHAR(255)
);

-- ---------------------------------------------------------------------------
-- products         (DynamoDB: products, HASH title, GSI product_id on productid)
-- price is a String in the entity, so it stays VARCHAR here.
-- category holds productcategory.type.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS products (
    productid  VARCHAR(255) PRIMARY KEY,
    title      VARCHAR(255) NOT NULL UNIQUE,
    price      VARCHAR(255),
    imageurl   VARCHAR(255),
    category   VARCHAR(255)
);

-- ---------------------------------------------------------------------------
-- shoppingcart     (DynamoDB: shoppingcart, HASH cartid)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS shoppingcart (
    cartid        VARCHAR(255) PRIMARY KEY,
    createddate   TIMESTAMP,
    modifieddate  TIMESTAMP
);

-- ShoppingCart.items (Map<productid, quantity>) -> element collection
CREATE TABLE IF NOT EXISTS shoppingcart_items (
    cartid     VARCHAR(255) NOT NULL REFERENCES shoppingcart(cartid),
    productid  VARCHAR(255) NOT NULL,
    quantity   INTEGER,
    PRIMARY KEY (cartid, productid)
);

-- ---------------------------------------------------------------------------
-- orders           (DynamoDB: orders, HASH orderid, GSI useridx_id on userid)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS orders (
    orderid    VARCHAR(255) PRIMARY KEY,
    userid     VARCHAR(255),
    orderdate  TIMESTAMP,
    name       VARCHAR(255),
    addline1   VARCHAR(255),
    addline2   VARCHAR(255),
    city       VARCHAR(255),
    state      VARCHAR(255),
    zipcode    VARCHAR(255)
);

CREATE INDEX IF NOT EXISTS orders_userid_idx ON orders (userid);

-- Orders.products (List<OrderProducts>) -> ordered element collection.
-- A snapshot of the product at order time, so there's no FK to products.
CREATE TABLE IF NOT EXISTS order_products (
    orderid   VARCHAR(255) NOT NULL REFERENCES orders(orderid),
    position  INTEGER      NOT NULL,
    title     VARCHAR(255),
    price     VARCHAR(255),
    imageurl  VARCHAR(255),
    quantity  INTEGER      NOT NULL,
    PRIMARY KEY (orderid, position)
);

